"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 6 (P1 v0.3, section 4): remove pool clips that match a MUSAN noise file (VoxTurn trained on MUSAN).

MUSAN's free-sound files carry no Freesound IDs, so matching is by audio fingerprint, with the threshold calibrated in
scripts/step0_fingerprint.py (results/step0/fingerprint_groups.json). Every MUSAN noise file (free-sound and
sound-bible) is queried against the index of pool clips.
usage: python -I scripts/step0_musan_match.py <clip dir> <fp selection json> <musan noise dir> <fingerprint json> <out json>
"""
import glob
import json
import os
import sys

sys.path.insert(0, os.path.dirname(__file__))
import step0_fingerprint as F  # noqa: E402


def main(clip_dir, sel_path, musan_dir, fp_path, out_path):
    sel = json.load(open(sel_path, encoding="utf-8"))
    thr = json.load(open(fp_path, encoding="utf-8"))["threshold_aligned_matches"]
    ids = sorted(k for k in sel if os.path.exists(os.path.join(clip_dir, k + ".wav")))
    fps = [F.fingerprint(F.load(os.path.join(clip_dir, k + ".wav"))) for k in ids]
    index = F.Index(fps)
    musan = sorted(glob.glob(os.path.join(musan_dir, "*", "*.wav")))
    matches = []
    for p in musan:
        h, t = F.fingerprint(F.load(p))
        for j, c in index.best(h, t).items():
            if c >= thr:
                matches.append({"musan": os.path.relpath(p, musan_dir).replace("\\", "/"), "clip": ids[j],
                                "pool_class": sel[ids[j]]["class"], "count": int(c)})
    excluded = sorted({m["clip"] for m in matches}, key=int)
    json.dump({"threshold": thr, "n_musan_files": len(musan), "n_pool_clips": len(ids), "matches": matches,
               "excluded_clips": excluded}, open(out_path, "w", encoding="utf-8"), indent=1)
    print(f"MUSAN files {len(musan)}, pool clips {len(ids)}, threshold {thr}: {len(matches)} matches, "
          f"{len(excluded)} pool clips excluded")
    for m in matches:
        print("  ", m)


if __name__ == "__main__":
    main(*sys.argv[1:6])
